/**
 * Render the IP check page.
 *
 * Every visitor-controlled value is escaped here. The nonce is generated by
 * this process and must match the Content-Security-Policy script-src nonce.
 *
 * Invariant: ip, browser name, browser version, and ISP cannot introduce tags.
 */

'use strict';

const { escapeHtml } = require('../escape-html/escape-html');

function renderPage({ ip, browserName, browserVersion, isp, nonce }) {
  if (!/^[A-Za-z0-9_-]+$/.test(nonce)) {
    throw new Error('invalid script nonce');
  }

  const safeIp = escapeHtml(ip);
  const safeName = escapeHtml(browserName);
  const safeVersion = escapeHtml(browserVersion);
  const safeIsp = escapeHtml(isp);

  return `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>IP: ${safeIp}</title>
<meta name="title" content="IP No BS">
<meta name="description" content="Returns the IP and browser version of your current connection.">
<meta name="keywords" content="what is my ip, my ip, ip address, browser version, ipv4, what's my ip">
<meta name="robots" content="index, follow">
<meta name="language" content="English">
<meta name="revisit-after" content="10 days">
<meta name="author" content="Gabriel Slayton">
<meta name="viewport" content="width=device-width, initial-scale=1">
<style>
body {
    background-color: #000000;
    color: #ffffff;
    font-family: Arial, Helvetica, sans-serif;
    font-size: 1.5em;
    text-align: center;
    margin-top: 10%;
}
.footer {
    position: fixed;
    bottom: 10px;
    width: 100%;
    text-align: center;
    color: #ffffff;
}
p a {
    color: #ffffff;
    text-decoration: none;
}
</style>
</head>
<body>
<script nonce="${nonce}" async src="https://www.googletagmanager.com/gtag/js?id=G-68ZJDQH8YZ"></script>
<script nonce="${nonce}">
  window.dataLayer = window.dataLayer || [];
  function gtag(){dataLayer.push(arguments);}
  gtag('js', new Date());
  gtag('config', 'G-68ZJDQH8YZ');
</script>
<h1>IP address: ${safeIp}</h1>
<h1>Browser: ${safeName} version ${safeVersion}</h1>
<h1>ISP: ${safeIsp}</h1>
<script nonce="${nonce}" async src="https://js.stripe.com/v3/buy-button.js"></script>
<stripe-buy-button
  buy-button-id="buy_btn_1NiO2oEPb7xHDOFyKoygn0os"
  publishable-key="pk_live_51Ne1OuEPb7xHDOFyN3seam6hy5oV2HPmDSFRbTcPuy0rKC3jqmj23Zys6dvbZ2xLWlbLlOrkzeQjA7wDqWCq3Ob600Z2VISyFc">
</stripe-buy-button>
<div class="footer">
<p>Gabriel Slayton - <a href="https://www.slaytons.net">Slayton's Technology Services</a></p>
</div>
</body>
</html>`;
}

module.exports = { renderPage };
